<?php
include './globals/checks.php'; require_once '../src/connection.php';
if(empty($_SESSION['ra_admin_csrf']))$_SESSION['ra_admin_csrf']=bin2hex(random_bytes(32));$csrf=$_SESSION['ra_admin_csrf'];
function reh($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
$table='reading_activity_table';$cols=[];$pk=null;$r=$mysqli->query("SHOW COLUMNS FROM `$table`");if($r)while($c=$r->fetch_assoc()){$cols[$c['Field']]=$c;if($pk===null&&strpos($c['Extra']??'','auto_increment')!==false)$pk=$c['Field'];}if(!$pk)foreach(['id','activity_id','reading_activity_id'] as $k)if(isset($cols[$k])){$pk=$k;break;}if(!$pk)exit('Cannot identify activity primary key.');
$id=(string)($_GET['id']??$_POST['activity_id']??'');if(!ctype_digit($id)){header('Location: reading_activities.php');exit;}$n=(int)$id;$fields=['title','file_url','file_type','department','year_level','section','description','required_reading_minutes','start_date','due_date','status'];$s=$mysqli->prepare("SELECT `".$pk."`,".implode(',',$fields)." FROM `$table` WHERE `$pk`=? LIMIT 1");$s->bind_param('i',$n);$s->execute();$row=$s->get_result()->fetch_assoc();$s->close();if(!$row){http_response_code(404);exit('Reading activity not found.');}
$error='';$success='';if($_SERVER['REQUEST_METHOD']==='POST'){
 if(empty($_POST['csrf_token'])||!hash_equals($csrf,(string)$_POST['csrf_token']))$error='Security token expired. Refresh and retry.';
 else{foreach($fields as $f)$row[$f]=trim((string)($_POST[$f]??''));$row['required_reading_minutes']=(int)$row['required_reading_minutes'];
 if($row['title']==='')$error='Title is required.';elseif(!filter_var($row['file_url'],FILTER_VALIDATE_URL))$error='Enter a valid URL.';elseif(!in_array($row['file_type'],['pdf','doc','docx','ppt','pptx'],true))$error='Invalid file type.';elseif($row['department']==='')$error='Department is required.';elseif($row['year_level']==='')$error='Year level is required.';elseif($row['required_reading_minutes']<1||$row['required_reading_minutes']>1440)$error='Required reading time must be 1–1440 minutes.';elseif(!$row['start_date']||!$row['due_date']||strtotime($row['due_date'])<=strtotime($row['start_date']))$error='Due date must be later than start date.';elseif(!in_array($row['status'],['active','inactive'],true))$error='Invalid status.';
 if(!$error){$start=date('Y-m-d H:i:s',strtotime($row['start_date']));$due=date('Y-m-d H:i:s',strtotime($row['due_date']));$sql="UPDATE `$table` SET title=?,file_url=?,file_type=?,department=?,year_level=?,section=?,description=?,required_reading_minutes=?,start_date=?,due_date=?,status=? WHERE `$pk`=?";$u=$mysqli->prepare($sql);if($u){$u->bind_param('sssssssisssi',$row['title'],$row['file_url'],$row['file_type'],$row['department'],$row['year_level'],$row['section'],$row['description'],$row['required_reading_minutes'],$start,$due,$row['status'],$n);if($u->execute()){$success='Reading activity saved.';$row['start_date']=$start;$row['due_date']=$due;}else$error='Could not save changes.';$u->close();}else$error='Could not prepare update.';}}
}
foreach(['start_date','due_date'] as $f)$row[$f]=date('Y-m-d\TH:i',strtotime($row[$f]));$departments=[];$r=$mysqli->query("SELECT DISTINCT department FROM accounts WHERE access='student' AND department IS NOT NULL AND department<>'' ORDER BY department");if($r)while($x=$r->fetch_assoc())$departments[]=$x['department'];$years=[];$sections=[];$r=$mysqli->query("SELECT DISTINCT year_section FROM accounts WHERE access='student' AND year_section IS NOT NULL AND year_section<>''");if($r)while($x=$r->fetch_assoc()){$p=preg_split('/[-\s]+/',trim($x['year_section']),2);if(!empty($p[0]))$years[]=$p[0];if(!empty($p[1]))$sections[]=$p[1];}$years=array_unique($years);$sections=array_unique($sections);sort($years);sort($sections);
?>
