.php?id=<?=reh($id)?>"><input type="hidden" name="csrf_token" value="<?=reh($csrf)?>"><input type="hidden" name="activity_id" value="<?=reh($id)?>"><div class="row g-3">
<div class="col-12"><label class="form-label" for="title">Activity title *</label><input class="form-control" id="title" name="title" required maxlength="255" value="<?=reh($row['title'])?>"></div><div class="col-12"><label class="form-label" for="file_url">Reading material URL *</label><input class="form-control" type="url" id="file_url" name="file_url" required value="<?=reh($row['file_url'])?>"></div>
<div class="col-md-6"><label class="form-label" for="file_type">File type</label><select class="form-select" id="file_type" name="file_type"><?php foreach(['pdf'=>'PDF','doc'=>'Word (.doc)','docx'=>'Word (.docx)','ppt'=>'PowerPoint (.ppt)','pptx'=>'PowerPoint (.pptx)'] as $v=>$label):?><option value="<?=reh($v)?>" <?=$row['file_type']===$v?'selected':''?>><?=reh($label)?></option><?php endforeach;?></select></div><div class="col-md-6"><label class="form-label" for="required_reading_minutes">Required reading minutes *</label><input class="form-control" type="number" min="1" max="1440" id="required_reading_minutes" name="required_reading_minutes" required value="<?=reh($row['required_reading_minutes'])?>"></div>
<div class="col-md-4"><label class="form-label" for="department">Department *</label><select class="form-select" id="department" name="department" required><option value="">Select department</option><?php if(!in_array($row['department'],$departments,true))$departments[]=$row['department'];foreach($departments as $d):?><option value="<?=reh($d)?>" <?=$row['department']===$d?'selected':''?>><?=reh($d)?></option><?php endforeach;?></select></div><div class="col-md-4"><label class="form-label" for="year_level">Year level *</label><select class="form-select" id="year_level" name="year_level" required><option value="">Select year</option><?php if(!in_array($row['year_level'],$years,true))$years[]=$row['year_level'];foreach($years as $y):?><option value="<?=reh($y)?>" <?=$row['year_level']===$y?'selected':''?>><?=reh($y)?></option><?php endforeach;?></select></div><div class="col-md-4"><label class="form-label" for="section">Section</label><select class="form-select" id="section" name="section"><option value="">All sections</option><?php if($row['section']&&!in_array($row['section'],$sections,true))$sections[]=$row['section'];foreach($sections as $sec):?><option value="<?=reh($sec)?>" <?=$row['section']===$sec?'selected':''?>><?=reh($sec)?></option><?php endforeach;?></select></div>
<div class="col-md-6"><label class="form-label" for="start_date">Available from *</label><input class="form-control" type="datetime-local" id="start_date" name="start_date" required value="<?=reh($row['start_date'])?>"></div><div class="col-md-6"><label class="form-label" for="due_date">Due date *</label><input class="form-control" type="datetime-local" id="due_date" name="due_date" required value="<?=reh($row['due_date'])?>"></div><div class="col-md-6"><label class="form-label" for="status">Status</label><select class="form-select" id="status" name="status"><option value="active" <?=$row['status']==='active'?'selected':''?>>Active</option><option value="inactive" <?=$row['status']==='inactive'?'selected':''?>>Inactive</option></select></div><div class="col-12"><label class="form-label" for="description">Instructions</label><textarea class="form-control" id="description" name="description" rows="5"><?=reh($row['description'])?></textarea></div></div><div class="ra-actions"><a class="ra-btn" href="reading_activities.php">Cancel</a><button class="ra-btn ra-primary" type="submit">Save Changes</button></div></form></div></section></div></main><?php include 'globals/scripts.php';?></body></html>
